// Package multirun holds two types generated by two separate deep-gen runs
// over the same package — the documented workflow for splitting generation.
// Both types carry map fields; a shared package-level helper emitted by each
// run used to collide. The two checked-in files compiling together is the
// regression guard.
package multirun

//go:generate go run github.com/brunoga/deep/v6/cmd/deep-gen -type=Alpha -output alpha_deep.go .
//go:generate go run github.com/brunoga/deep/v6/cmd/deep-gen -type=Beta -output beta_deep.go .

type Alpha struct {
	M map[string]int `json:"m"`
}

type Beta struct {
	M map[string]string `json:"m"`
}
